#!/usr/bin/env node
// Screenshots of the documentation (spec 28, M4): generated by Playwright on
// the demo data, in light and dark theme, regenerated at every release so
// they never go stale. Output: src/assets/screenshots/{light,dark}/<name>.png.
//
// Design (owner: docs builder): the specs live in docs-site/screenshots/
// and run with the Playwright install of e2e/ (one browser download for the
// repository), against a fresh `arenile` binary seeded with `seed demo`,
// exactly like the end-to-end tests:
//   e2e/node_modules/.bin/playwright test -c docs-site/screenshots/playwright.config.ts
// `make docs-screenshots` builds the SPAs and runs this script.
import { existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';

const here = dirname(fileURLToPath(import.meta.url));
const root = join(here, '..', '..');
const config = join(root, 'docs-site', 'screenshots', 'playwright.config.ts');
const playwright = join(root, 'e2e', 'node_modules', '.bin', 'playwright');

if (!existsSync(config)) {
  console.log('docs-screenshots: no docs-site/screenshots/playwright.config.ts yet, nothing to do');
  process.exit(0);
}
if (!existsSync(playwright)) {
  console.error('docs-screenshots: Playwright not installed, run `make setup` first');
  process.exit(1);
}
const res = spawnSync(playwright, ['test', '-c', config], { cwd: root, stdio: 'inherit' });
process.exit(res.status ?? 1);
